function cima(x, z) {
  x = Math.floor(x); z = Math.floor(z);
  if (!mcInside(x, 0, z)) return -1;
  for (let y = mc.dim.y - 1; y >= 0; y--) if (mc.grid[mcIdx(x, y, z)]) return y;
  return -1;
}

var osd_sitio = 'abajo-derecha';
game.osd.define('mi_menu', {
  sitio: osd_sitio,
  showTool: false,
  html: '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">Mi OSD</div>' +
    '<button class="mc-osd-btn">INTRO</button>' +
    '<button class="mc-osd-btn">AJUSTES</button>' +
    '<button class="mc-osd-btn">ENTORNO</button>' +
    '<button class="mc-osd-btn">EFECTOS</button>' +
    '<button class="mc-osd-btn">AGENTE</button>' +
    '<button class="mc-osd-btn">CERRAR</button>' +
    '</div>'
});

const htmlVolar = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">FISICAS</div>'
  + '<button class="mc-osd-btn" data-osd="VOLAR">VOLAR: ' + (game.volar.valueOf() ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="FANTASMA">FANTASMA: ' + (game.fantasma.valueOf() ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="SPEED">SPEED: ' + (game.playerSpeed == 4 ? 'NORMAL' : 'FAST') + '</button>'
  + '<button class="mc-osd-btn">REGRESAR</button>'
  + '</div>';

const htmlEfectos = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">EFECTOS</div>'
  + '<button class="mc-osd-btn" data-osd="ESTRELLAS">✨ ESTRELLAS: ' + (game.efectos.estrellas._on ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="PETALOS">🌸 PÉTALOS: ' + (game.efectos.petalosSakura && game.efectos.petalosSakura.porSegundo != 0 ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="LUCIERNAGAS">🏮 LUCIÉRNAGAS: ' + (game.efectos.luciernagas && game.efectos.luciernagas.porSegundo != 0 ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="LLUVIA">🌧️ LLUVIA: ' + (game.efectos.lluvia.porSegundo != 0 ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="NIEVE">❄️ NIEVE: ' + (game.efectos.nieve.porSegundo != 0 ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn">REGRESAR</button>'
  + '</div>';

let buttons = "";
game.entorno().forEach(entorno => {
  buttons += `<button class="mc-osd-btn" data-osd="${entorno}">${entorno}</button>`;
});

const htmlEntorno = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">ENTORNO</div>'
  + buttons
  + '<button class="mc-osd-btn">REGRESAR</button>'
  + '</div>';

game.osd.define('mi_menu_volar', { sitio: osd_sitio, showTool: false, html: htmlVolar() });
game.osd.define('mi_menu_entorno', { sitio: osd_sitio, showTool: false, hueco: 4, html: htmlEntorno() });
game.osd.define('mi_menu_efectos', { sitio: osd_sitio, showTool: false, html: htmlEfectos() });

game.osd.alPulsar('INTRO', () => { game.snippet("arranque-intro"); });
game.osd.alPulsar('AJUSTES', () => { game.osd.conmutar("mi_menu_volar"); });
game.osd.alPulsar('ENTORNO', () => { game.osd.conmutar("mi_menu_entorno"); });
game.osd.alPulsar('EFECTOS', () => { game.osd.conmutar("mi_menu_efectos"); });

game.entorno().forEach(entorno => {
  game.osd.alPulsar(entorno, () => { game.entorno(entorno, 1); });
});

game.osd.alPulsar('PETALOS', () => {
  const S = game.efectos.petalosSakura;
  if (S) {
    if (S.porSegundo == 0) S.enciende(65);
    else S.para();
  }
  game.osd.define('mi_menu_efectos', { sitio: osd_sitio, html: htmlEfectos() });
  game.osd.abrir('mi_menu_efectos');
});

game.osd.alPulsar('LUCIERNAGAS', () => {
  const L = game.efectos.luciernagas;
  if (L) {
    if (L.porSegundo == 0) L.enciende(26);
    else L.para();
  }
  game.osd.define('mi_menu_efectos', { sitio: osd_sitio, html: htmlEfectos() });
  game.osd.abrir('mi_menu_efectos');
});

game.osd.alPulsar('LLUVIA', () => {
  const Ll = game.efectos.lluvia;
  if (Ll.porSegundo == 0) Ll.enciende(150);
  else Ll.para();

  game.osd.define('mi_menu_efectos', { sitio: osd_sitio, html: htmlEfectos() });
  game.osd.abrir('mi_menu_efectos');
});

game.osd.alPulsar('NIEVE', () => {
  const N = game.efectos.nieve;
  if (N.porSegundo == 0) N.enciende(150);
  else N.para();

  game.osd.define('mi_menu_efectos', { sitio: osd_sitio, html: htmlEfectos() });
  game.osd.abrir('mi_menu_efectos');
});

game.osd.alPulsar('ESTRELLAS', () => {
  const Est = game.efectos.estrellas;
  if (Est._on == false) Est.enciende();
  else Est.apaga();

  game.osd.define('mi_menu_efectos', { sitio: osd_sitio, html: htmlEfectos() });
  game.osd.abrir('mi_menu_efectos');
});

game.osd.alPulsar('AGENTE', () => {
  const [xp, yp0, zp] = game.aim();
  const yp = cima(xp, zp) + 1;
  game.esqueletos.crear("luciernaga", xp, yp, zp);
});

game.osd.alPulsar('VOLAR', () => {
  game.volar();
  game.osd.define('mi_menu_volar', { sitio: osd_sitio, html: htmlVolar() });
  game.osd.abrir('mi_menu_volar');
});

game.osd.alPulsar('FANTASMA', () => {
  game.fantasma();
  game.osd.define('mi_menu_volar', { sitio: osd_sitio, html: htmlVolar() });
  game.osd.abrir('mi_menu_volar');
});

game.osd.alPulsar('SPEED', () => {
  game.playerSpeed = game.playerSpeed == 4 ? 100 : 4;
  game.osd.define('mi_menu_volar', { sitio: osd_sitio, html: htmlVolar() });
  game.osd.abrir('mi_menu_volar');
});

game.osd.alPulsar('REGRESAR', () => { game.osd.conmutar("mi_menu"); });
game.osd.alPulsar('CERRAR', () => { game.osd.cerrar(); });

if (noshow == false) game.osd.abrir('mi_menu');

game.onKey('o', () => {
  game.osd.abrir('mi_menu');
});
